import type { PoolClient } from "pg";
import { pool } from "./pool";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Runs fn inside a transaction in which RLS sees `userId` as the current user.
 *
 * The setting is transaction-local (set_config(..., true)), so it ends with
 * COMMIT/ROLLBACK and can't leak to the next request that reuses this pooled
 * connection. All task queries must go through here.
 */
export async function withUser<T>(userId: string, fn: (client: PoolClient) => Promise<T>): Promise<T> {
  if (!UUID_RE.test(userId)) throw new Error("withUser: userId must be a UUID");

  const client = await pool.connect();
  let broken: Error | undefined;
  try {
    await client.query("BEGIN");
    await client.query("SELECT set_config('app.user_id', $1, true)", [userId]);
    const result = await fn(client);
    await client.query("COMMIT");
    return result;
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Connection is unusable; make release() destroy it instead of pooling it.
      broken = rollbackErr as Error;
    }
    throw err;
  } finally {
    client.release(broken);
  }
}

import path from "node:path";
import { defineConfig } from "vitest/config";
import { loadEnv, requireEnv } from "./scripts/env";

loadEnv();

export default defineConfig({
  resolve: {
    alias: { "@": path.resolve(import.meta.dirname, "src") },
  },
  test: {
    include: ["tests/**/*.test.ts"],
    globalSetup: ["tests/setup/globalSetup.ts"],
    // Integration test files share one database and truncate it; run them serially.
    fileParallelism: false,
    env: {
      // App code (src/lib/db/pool.ts) reads DATABASE_URL; point it at the test DB.
      DATABASE_URL: requireEnv("TEST_DATABASE_URL"),
    },
  },
});

// Runs once before the test run: checks the test database is reachable and
// migrates it. Fails loudly (never skips) if Postgres isn't available.
import pg from "pg";
import { loadEnv, requireEnv } from "../../scripts/env";
import { migrate } from "../../scripts/migrate";

const HINT = "Start it with: npm run db:up && npm run db:migrate";

export default async function setup() {
  loadEnv();
  const ownerUrl = requireEnv("TEST_MIGRATION_DATABASE_URL");
  const appUrl = requireEnv("TEST_DATABASE_URL");

  // Tests truncate tables, so refuse to point them at anything but a *_test DB.
  for (const url of [ownerUrl, appUrl]) {
    const db = new URL(url).pathname.slice(1);
    if (!db.endsWith("_test")) {
      throw new Error(`Refusing to run tests against database "${db}": test URLs must point at a *_test database.`);
    }
  }

  await assertReachable(ownerUrl, "owner");
  await migrate({ label: "test", ownerUrl, appUrl });
  await assertReachable(appUrl, "app_user");
}

async function assertReachable(url: string, who: string) {
  const client = new pg.Client({ connectionString: url, connectionTimeoutMillis: 3000 });
  try {
    await client.connect();
    await client.query("SELECT 1");
  } catch (err) {
    const { host, port, pathname } = new URL(url);
    throw new Error(
      `\n\nTests need Postgres, but connecting as ${who} to ${host}:${port}${pathname} failed:\n` +
        `  ${(err as Error).message}\n${HINT}\n`,
    );
  } finally {
    await client.end().catch(() => {});
  }
}

