  | { kind: "invalid"; row: number; reasons: string[]; data: RawRow }
  | { kind: "valid"; row: number; input: TaskInput; data: RawRow };

export const TOO_MANY_FIELDS = "Too many fields (check for an unquoted comma)";

const FIELD_ORDER = ["title", "due_date", "priority", "notes"] as const;

export function isBlankRecord(cells: string[]): boolean {
  return cells.every((c) => c.trim() === "");
}

export function rawRow(record: CsvRecord, columns: ParsedCsv["columns"]): RawRow {
  const cell = (i: number | undefined) => (i === undefined ? "" : (record.cells[i] ?? ""));
  return {
    title: cell(columns.title),
    due_date: cell(columns.due_date),
    priority: cell(columns.priority),
    notes: cell(columns.notes),
  };
}

export function validateRecord(record: CsvRecord, csv: Pick<ParsedCsv, "header" | "columns">): RecordResult {
  const { row, cells } = record;
  if (isBlankRecord(cells)) return { kind: "blank", row };

  const data = rawRow(record, csv.columns);

  // Values are shifted, so per-field errors would be misleading; this is the only reason.
  if (cells.length > csv.header.length) return { kind: "invalid", row, reasons: [TOO_MANY_FIELDS], data };

  // Missing trailing cells are "" (see rawRow) and are reported by the schema.
  const parsed = taskInputSchema.safeParse({ ...data, status: "todo" });
  if (parsed.success) return { kind: "valid", row, input: parsed.data, data };

  const byField = new Map<string, string[]>();
  for (const issue of parsed.error.issues) {
    const field = String(issue.path[0]);
    const list = byField.get(field) ?? [];
    list.push(issue.message.replace(/\.$/, ""));
    byField.set(field, list);
  }
  const reasons = FIELD_ORDER.flatMap((f) => byField.get(f) ?? []);
  return { kind: "invalid", row, reasons, data };
}

export function joinReasons(reasons: string[]): string {
  return reasons.join("; ");
}

// In-file duplicate detection. Pure.
import type { TaskInput } from "@/lib/tasks/schema";
import type { RejectedRow, ValidRow } from "./validate";

/** Duplicate key: exact trimmed title + due date (titles are already trimmed by the schema). */
export function duplicateKey(t: Pick<TaskInput, "title" | "due_date">): string {
  return `${t.title}\u0000${t.due_date}`;
}

/**
 * The first VALID row with a given key wins; later valid rows with the same key
 * are rejected as "Duplicate of row N". Invalid rows never claim a key, so a
 * valid row after an invalid one with the same title/date is not a duplicate.
 * Input must be in file order.
 */
export function splitInFileDuplicates(validRows: ValidRow[]): { unique: ValidRow[]; duplicates: RejectedRow[] } {
  const firstRowByKey = new Map<string, number>();
  const unique: ValidRow[] = [];
  const duplicates: RejectedRow[] = [];
  for (const r of validRows) {
    const key = duplicateKey(r.input);
    const first = firstRowByKey.get(key);
    if (first === undefined) {
      firstRowByKey.set(key, r.row);
      unique.push(r);
    } else {
      duplicates.push({ row: r.row, reason: `Duplicate of row ${first}`, data: r.data });
    }
  }
  return { unique, duplicates };
}

// Rejected rows -> downloadable CSV. Pure; runs in the browser too.
import Papa from "papaparse";
import type { RejectedRow } from "./validate";

export const REJECTED_CSV_COLUMNS = ["title", "due_date", "priority", "notes", "row_number", "reason"] as const;

/**
 * RFC 4180 output (CRLF; fields with commas, quotes or line breaks are quoted).
 * Cells starting with = + - @ get a leading single quote so spreadsheet apps
 * don't evaluate them as formulas (CSV injection).
 */
export function buildRejectedCsv(rows: RejectedRow[]): string {
  return Papa.unparse(
    {
      fields: [...REJECTED_CSV_COLUMNS],
      data: rows.map((r) => [r.data.title, r.data.due_date, r.data.priority, r.data.notes, String(r.row), r.reason]),
    },
    { newline: "\r\n", escapeFormulae: /^[=+\-@]/ },
  );
}

// Whole-file pipeline without the database: parse -> validate -> in-file dedupe.
// The service (DB insert, account duplicates) builds on this.
import { duplicateKey, splitInFileDuplicates } from "./dedupe";
import { parseCsv } from "./parse";
import { joinReasons, validateRecord, type RejectedRow, type ValidRow } from "./validate";

export type Analysis =
  | { ok: false; error: string }
  | {
      ok: true;
      /** Data rows in the file (blank ones included; header and final line break excluded). */
      totalRows: number;
      skippedBlank: number;
      /** Valid and unique within the file, in file order. */
      valid: ValidRow[];
      /** Sorted by row number. */
      rejected: RejectedRow[];
    };

export function analyzeCsv(text: string): Analysis {
  const parsed = parseCsv(text);
  if (!parsed.ok) return parsed;
  const { csv } = parsed;

  let skippedBlank = 0;
  const valid: ValidRow[] = [];
  const rejected: RejectedRow[] = [];
  for (const record of csv.records) {
    const r = validateRecord(record, csv);
    if (r.kind === "blank") skippedBlank++;
    else if (r.kind === "invalid") rejected.push({ row: r.row, reason: joinReasons(r.reasons), data: r.data });
    else valid.push({ row: r.row, input: r.input, data: r.data });
  }

  const { unique, duplicates } = splitInFileDuplicates(valid);
  return {
    ok: true,
    totalRows: csv.records.length,
    skippedBlank,
    valid: unique,
    rejected: sortByRow([...rejected, ...duplicates]),
  };
}

export function sortByRow<T extends { row: number }>(rows: T[]): T[] {
  return [...rows].sort((a, b) => a.row - b.row);
}

export { duplicateKey };

