describe("row validation", () => {
  it("accepts a valid row and trims values", () => {
    expect(reasonFor("  Pay rent  , 2026-11-01 , 3 ,  notes ")).toBe("valid");
    expect(analyze(csv(HEADER, "  Pay rent  ,2026-11-01,3,  notes  ")).valid[0].input).toEqual({
