    expect(parsed.csv.records.map((r) => r.cells)).toEqual([
      ["", "2026-01-01", "high", 'has, comma and "quotes"\nand a newline', "7", rejected[0].reason],
      ["'=HYPERLINK(\"x\")", "'+1", "'-1", "'@cmd", "12", TOO_MANY_FIELDS],
