  if (!outcome.ok) throw new Error(`import failed: ${outcome.error}`);
  return outcome.result;
}

const reasons = (r: ImportResult) => r.rejected.map((x): [number, string] => [x.row, x.reason]);

beforeAll(async () => {
  await resetDb();
  userId = await createUser("demo@example.test");
  first = await upload();
  second = await upload();
});

afterAll(async () => {
  await pool.end();
  await ownerPool.end();
});

